public class HarnessFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.Harness> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.Harness>(resourceName)
{

    internal List<InnerHarnessHarnessToolFactory> ToolsFactories { get; set; } = [];

    internal List<InnerHarnessHarnessSkillFactory> SkillsFactories { get; set; } = [];

    internal List<InnerHarnessHarnessHookFactory> HooksFactories { get; set; } = [];

    internal List<InnerHarnessHarnessSystemContentBlockFactory> SystemPromptFactories { get; set; } = [];

    internal InnerHarnessHarnessMemoryConfigurationFactory MemoryFactory { get; set; }

    internal InnerHarnessHarnessTruncationConfigurationFactory TruncationFactory { get; set; }

    internal InnerHarnessHarnessEnvironmentArtifactFactory EnvironmentArtifactFactory { get; set; }

    internal InnerHarnessHarnessModelConfigurationFactory ModelFactory { get; set; }

    internal InnerHarnessHarnessEnvironmentProviderFactory EnvironmentFactory { get; set; }

    internal InnerHarnessAuthorizerConfigurationFactory AuthorizerConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.Harness Create()
    {
        var harnessResult = CreateHarness();
        factoryAction?.Invoke(harnessResult);

        return harnessResult;
    }

    private Humidifier.BedrockAgentCore.Harness CreateHarness()
    {
        var harnessResult = new Humidifier.BedrockAgentCore.Harness
        {
            GivenName = InputResourceName,
        };

        return harnessResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.Harness result)
    {
        base.CreateChildren(result);

        result.Tools = ToolsFactories.Any() ? ToolsFactories.Select(x => x.Build()).ToList() : null;
        result.Skills = SkillsFactories.Any() ? SkillsFactories.Select(x => x.Build()).ToList() : null;
        result.Hooks = HooksFactories.Any() ? HooksFactories.Select(x => x.Build()).ToList() : null;
        result.SystemPrompt = SystemPromptFactories.Any() ? SystemPromptFactories.Select(x => x.Build()).ToList() : null;
        result.Memory ??= MemoryFactory?.Build();
        result.Truncation ??= TruncationFactory?.Build();
        result.EnvironmentArtifact ??= EnvironmentArtifactFactory?.Build();
        result.Model ??= ModelFactory?.Build();
        result.Environment ??= EnvironmentFactory?.Build();
        result.AuthorizerConfiguration ??= AuthorizerConfigurationFactory?.Build();
    }

} // End Of Class

